fn test_a_ring_has_a_hole_and_a_component_inside_it_has_the_ring_as_parent() {
    let b: &crate::port::Bitmap = &crate::port::bitmap_new(120, 120, 1);
    let comps: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let rules: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let prims: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let tlines: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pts: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let refs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let views: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let inks: &mut crate::port::Cells = &mut crate::port::Cells::new();
    tt_rect(b, 4, 4, 48, 48);
    // carve the hole: clear the inner block
    let mut x: i32 = 7;
    let mut y: i32 = 7;
    while y < 45 {
        x = 7;
        while x < 45 {
            crate::port::bitmap_set_u8(b, x, y, 0, 0);
            x += 1;
        }
        y += 1;
    }
    tt_rect(b, 20, 20, 32, 32);
    tt_field(b);
    tt_trace(b, 7200, comps, rules, prims, tlines, pts, refs, views, inks);
    crate::testport::assert_eq(co_count(comps), 52, "the frame, the block inside it and the fifty glyphs");
    crate::testport::assert_eq(co_get(comps, 0, cf_holes()), 1, "the frame has one hole");
    crate::testport::assert_eq(co_get(comps, 0, cf_parent()), -1, "and no parent");
    crate::testport::assert_eq(co_get(comps, 1, cf_parent()), 0, "the block lies in the frame's hole");
    crate::testport::assert_eq(co_get(comps, 1, cf_holes()), 0, "and has none");
}
