#[test]
fn test_noise_glyphs_rules_and_large_things_are_told_apart() {
    let b: &crate::port::Bitmap = &crate::port::bitmap_new(200, 160, 1);
    let comps: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let rules: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let prims: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let tlines: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pts: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let refs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let views: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let inks: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let mut i: i32 = 0;
    let mut r: i32 = 0;
    // thirty glyph-sized blocks in three rows, a speck, a tall thin bar (a rule), a long thin one, and a big block
    while r < 3 {
        i = 0;
        while i < 10 {
            tt_rect(b, 4 + (i * 10), 4 + (r * 12), 10 + (i * 10), 12 + (r * 12));
            i += 1;
        }
        r += 1;
    }
    tt_dot(b, 190, 5);
    tt_rect(b, 170, 60, 172, 90);
    tt_rect(b, 4, 100, 150, 102);
    tt_rect(b, 4, 110, 60, 148);
    tt_trace(b, 7200, comps, rules, prims, tlines, pts, refs, views, inks);
    crate::testport::assert_eq(co_count(comps), 34, "thirty-four components");
    crate::testport::assert_eq(co_get(comps, 0, cf_kind()), ck_text_like(), "a glyph-sized block is text-like");
    crate::testport::assert_eq(co_get(comps, 0, cf_conf()), 900, "with confidence 900");
    // sorted by top: the first row (y 4), the speck (y 5), the second and third rows, the tall bar, the long bar, the big block
    crate::testport::assert_eq(co_get(comps, 10, cf_kind()), ck_blob(), "the speck is blob (noise)");
    crate::testport::assert_eq(co_get(comps, 10, cf_conf()), 0, "with confidence 0");
    crate::testport::assert_eq(co_get(comps, 31, cf_kind()), ck_rule_v(), "the tall thin bar is a vertical rule");
    crate::testport::assert_eq(co_get(comps, 32, cf_kind()), ck_rule_h(), "the long thin one is a horizontal rule");
    crate::testport::assert_eq(co_get(comps, 33, cf_kind()), ck_blob(), "the big block is large (blob)");
    crate::testport::assert_eq(co_get(comps, 33, cf_conf()), 700, "with confidence 700");
}
