#[test]
fn test_douglas_peucker_drops_a_staircase_and_keeps_a_corner() {
    let raw: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let keep: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let stk: &mut crate::port::Cells = &mut crate::port::Cells::new();
    // an open chain along a gentle line with one-pixel wobble, then a real corner
    crate::port::cells_push(raw, 0);
    crate::port::cells_push(raw, 0);
    crate::port::cells_push(raw, 5);
    crate::port::cells_push(raw, 1);
    crate::port::cells_push(raw, 10);
    crate::port::cells_push(raw, 0);
    crate::port::cells_push(raw, 15);
    crate::port::cells_push(raw, 1);
    crate::port::cells_push(raw, 20);
    crate::port::cells_push(raw, 0);
    crate::testport::assert_eq(tr_simplify(raw, 5, 0, 9, keep, stk), 2, "the wobble is under 1.5 px: only the ends stay");
    crate::port::cells_push(raw, 20);
    crate::port::cells_push(raw, 20);
    crate::testport::assert_eq(tr_simplify(raw, 6, 0, 9, keep, stk), 3, "a corner 20 px off the chord stays");
    crate::testport::assert_eq(crate::port::cells_at(keep, 5), 1, "the end");
    let sq: &mut crate::port::Cells = &mut crate::port::Cells::new();
    crate::port::cells_push(sq, 0);
    crate::port::cells_push(sq, 0);
    crate::port::cells_push(sq, 10);
    crate::port::cells_push(sq, 0);
    crate::port::cells_push(sq, 10);
    crate::port::cells_push(sq, 10);
    crate::port::cells_push(sq, 0);
    crate::port::cells_push(sq, 10);
    crate::testport::assert_eq(tr_simplify(sq, 4, 1, 9, keep, stk), 4, "a closed square keeps its four corners");
}
